 "Un prompt flojo y uno bueno": "Un prompt fluix i un de bo",
 "<b style=\"font-size:28px;color:#c0455f\">Flojo</b><br><span style=\"font-size:23px;color:#1f2430\">«Háblame de la Revolución Francesa»<br><br><span style=\"font-size:19px;color:#5a5373\">Resultado: un texto largo y genérico que no responde a lo que necesitas.</span></span>": "<b style=\"font-size:28px;color:#c0455f\">Fluix</b><br><span style=\"font-size:23px;color:#1f2430\">«Parla'm de la Revolució Francesa»<br><br><span style=\"font-size:19px;color:#5a5373\">Resultat: un text llarg i genèric que no respon al que necessites.</span></span>",
